export const LIMIT_MINOR = 1000000;

export function approveOrder(store, id, by) {
  const order = getOrder(store, id);
  if (!order) return { error: "NOT_FOUND" };
  if (by?.role !== "manager") return { error: "FORBIDDEN" };
  return store.put("orders", id, { ...order, approved: true });
}

const held = (order) => Boolean(order) && order.state === "open" && order.totalMinor > LIMIT_MINOR && order.approved !== true;

export const confirmOrder = (store, id) => (held(getOrder(store, id)) ? { error: "FORBIDDEN" } : moved(store, id, "open", "confirmed"));
